using System.Reflection;
using System.Reflection.Emit;
using System.Reflection.Metadata;
using System.Reflection.Metadata.Ecma335;
using System.Reflection.PortableExecutable;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;

internal static class ConnectorEvidence
{
    static readonly Dictionary<ushort,OpCode> Opcodes=typeof(OpCodes).GetFields(BindingFlags.Public|BindingFlags.Static).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(op=>unchecked((ushort)op.Value));
    public static void Export(string root,string manifestName="connector-artifact-identities.json",string outputName="xaml-connector-evidence.json")
    {
        var output=Path.Combine(root,"docs/architecture-recovery");var manifest=JsonNode.Parse(File.ReadAllText(Path.Combine(output,manifestName)))!;var results=new List<object>();
        foreach(var artifact in manifest["artifacts"]!.AsArray()){
            var bytes=File.ReadAllBytes(artifact!["path"]!.GetValue<string>());if(Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant()!=artifact["sha256"]!.GetValue<string>())throw new InvalidDataException("Connector artifact hash changed.");
            using var pe=new PEReader(new MemoryStream(bytes));var md=pe.GetMetadataReader();if(md.GetGuid(md.GetModuleDefinition().Mvid).ToString()!=artifact["mvid"]!.GetValue<string>())throw new InvalidDataException("Connector MVID changed.");
            string TypeName(EntityHandle handle)=>handle.Kind switch{HandleKind.TypeDefinition=>TypeDefName((TypeDefinitionHandle)handle),HandleKind.TypeReference=>TypeRefName((TypeReferenceHandle)handle),_=>handle.Kind.ToString()};
            string TypeDefName(TypeDefinitionHandle handle){var t=md.GetTypeDefinition(handle);return md.GetString(t.Namespace)+"."+md.GetString(t.Name);}
            string TypeRefName(TypeReferenceHandle handle){var t=md.GetTypeReference(handle);return md.GetString(t.Namespace)+"."+md.GetString(t.Name);}
            int? ParameterCount(BlobHandle signature){try{var reader=md.GetBlobReader(signature);var header=reader.ReadSignatureHeader();if(header.Kind!=SignatureKind.Method)return null;if(header.IsGeneric)_=reader.ReadCompressedInteger();return reader.ReadCompressedInteger();}catch(BadImageFormatException){return null;}}
            object Symbol(int token){if((uint)token>>24==0x70)return new{token=$"0x{token:x8}",kind="user-string",value=md.GetUserString(MetadataTokens.UserStringHandle(token&0xffffff))};var handle=MetadataTokens.EntityHandle(token);if(handle.Kind==HandleKind.MethodDefinition){var m=md.GetMethodDefinition((MethodDefinitionHandle)handle);return new{token=$"0x{token:x8}",kind="method-def",type=TypeName(m.GetDeclaringType()),name=md.GetString(m.Name),parameters=ParameterCount(m.Signature),attributes=m.Attributes.ToString(),signatureBytes=Convert.ToHexString(md.GetBlobBytes(m.Signature)).ToLowerInvariant()};}if(handle.Kind==HandleKind.MethodSpecification){var spec=md.GetMethodSpecification((MethodSpecificationHandle)handle);return new{token=$"0x{token:x8}",kind="method-spec",definition=Symbol(MetadataTokens.GetToken(spec.Method)),instantiationSignatureBytes=Convert.ToHexString(md.GetBlobBytes(spec.Signature)).ToLowerInvariant()};}if(handle.Kind==HandleKind.FieldDefinition){var f=md.GetFieldDefinition((FieldDefinitionHandle)handle);return new{token=$"0x{token:x8}",kind="field-def",type=TypeName(f.GetDeclaringType()),name=md.GetString(f.Name),attributes=f.Attributes.ToString()};}if(handle.Kind==HandleKind.MemberReference){var m=md.GetMemberReference((MemberReferenceHandle)handle);return new{token=$"0x{token:x8}",kind="member-ref",type=TypeName(m.Parent),name=md.GetString(m.Name),parameters=ParameterCount(m.Signature),signatureBytes=Convert.ToHexString(md.GetBlobBytes(m.Signature)).ToLowerInvariant()};}return new{token=$"0x{token:x8}",kind=handle.Kind.ToString(),type=TypeName(handle)};}
            foreach(var target in manifest["targets"]!.AsArray().Where(t=>t!["artifact"]!.GetValue<string>()==artifact["key"]!.GetValue<string>())){
                var typeName=target!["type"]!.GetValue<string>();var exactTokens=target["methodTokens"]?.AsArray().Select(n=>Convert.ToInt32(n!.GetValue<string>().Replace("0x",""),16)).ToHashSet()??new HashSet<int>();
                var typeHandle=exactTokens.Count>0?md.GetMethodDefinition((MethodDefinitionHandle)MetadataTokens.EntityHandle(exactTokens.First())).GetDeclaringType():md.TypeDefinitions.Single(h=>TypeDefName(h)==typeName);
                if(TypeDefName(typeHandle)!=typeName||exactTokens.Any(token=>md.GetMethodDefinition((MethodDefinitionHandle)MetadataTokens.EntityHandle(token)).GetDeclaringType()!=typeHandle))throw new InvalidDataException("Exact method tokens do not share the requested type: requested="+typeName+", actual="+TypeDefName(typeHandle));
                var type=md.GetTypeDefinition(typeHandle);var handlerNames=target["handlers"]?.AsArray().Select(n=>n!.GetValue<string>()).ToHashSet(StringComparer.Ordinal)??new HashSet<string>(StringComparer.Ordinal);var methods=new List<object>();
                foreach(var handle in type.GetMethods()){
                    var method=md.GetMethodDefinition(handle);var name=md.GetString(method.Name);if(!exactTokens.Contains(MetadataTokens.GetToken(handle))&&!handlerNames.Contains(name)&&!name.EndsWith(".Connect",StringComparison.Ordinal)&&name!="_CreateDelegate")continue;
                    var rows=new List<object>();string status="absent";string? issue=null;byte[]? il=null;object[] exceptions=[];
                    if(method.RelativeVirtualAddress!=0){var body=pe.GetMethodBody(method.RelativeVirtualAddress);il=body.GetILBytes();exceptions=body.ExceptionRegions.Select(e=>(object)new{kind=e.Kind.ToString(),catchType=e.Kind==ExceptionRegionKind.Catch?TypeName(e.CatchType):null,e.TryOffset,e.TryLength,e.HandlerOffset,e.HandlerLength}).ToArray();status="decoded";try{int offset=0;while(offset<il!.Length){int start=offset;ushort code=il[offset++];if(code==0xfe)code=(ushort)(0xfe00|il[offset++]);if(!Opcodes.TryGetValue(code,out var op))throw new InvalidDataException("Unknown opcode.");object? value=null;int Int(){if(offset+4>il.Length)throw new BadImageFormatException();int v=BitConverter.ToInt32(il,offset);offset+=4;return v;}
                        switch(op.OperandType){case OperandType.InlineNone:break;case OperandType.ShortInlineI:value=(int)(sbyte)il[offset++];break;case OperandType.ShortInlineVar:value=(int)il[offset++];break;case OperandType.InlineVar:value=(int)BitConverter.ToUInt16(il,offset);offset+=2;break;case OperandType.InlineI:value=Int();break;case OperandType.InlineI8:value=BitConverter.ToInt64(il,offset);offset+=8;break;case OperandType.ShortInlineR:value=BitConverter.ToSingle(il,offset).ToString("R",System.Globalization.CultureInfo.InvariantCulture);offset+=4;break;case OperandType.InlineR:value=BitConverter.ToDouble(il,offset).ToString("R",System.Globalization.CultureInfo.InvariantCulture);offset+=8;break;case OperandType.ShortInlineBrTarget:{int delta=(sbyte)il[offset++];value=offset+delta;break;}case OperandType.InlineBrTarget:{int delta=Int();value=offset+delta;break;}case OperandType.InlineSwitch:{int count=Int();if(count<0||count>100000)throw new BadImageFormatException();var deltas=new int[count];for(int i=0;i<count;i++)deltas[i]=Int();int after=offset;value=deltas.Select(d=>after+d).ToArray();break;}case OperandType.InlineField:case OperandType.InlineMethod:case OperandType.InlineType:case OperandType.InlineTok:case OperandType.InlineString:case OperandType.InlineSig:value=Symbol(Int());break;default:throw new InvalidDataException("Unsupported operand.");}
                        rows.Add(new{offset=start,label=$"IL_{start:x4}",opcode=op.Name,operandKind=op.OperandType.ToString(),operand=value});if(offset>il.Length)throw new BadImageFormatException();}
                    }catch(Exception error)when(error is BadImageFormatException or InvalidDataException or IndexOutOfRangeException or ArgumentException){status="partial";issue=error.Message;}}
                    methods.Add(new{name,token=$"0x{MetadataTokens.GetToken(handle):x8}",symbol=Symbol(MetadataTokens.GetToken(handle)),status,issue,ilSize=il?.Length,ilSha256=il is null?null:Convert.ToHexString(SHA256.HashData(il)).ToLowerInvariant(),ilBytes=il is null?null:Convert.ToHexString(il).ToLowerInvariant(),instructions=rows,exceptions});
                }
                var layout=type.GetLayout();var fields=type.GetFields().Select(h=>{var f=md.GetFieldDefinition(h);return new{token=$"0x{MetadataTokens.GetToken(h):x8}",name=md.GetString(f.Name),attributes=f.Attributes.ToString(),offset=f.GetOffset(),signatureBytes=Convert.ToHexString(md.GetBlobBytes(f.Signature)).ToLowerInvariant(),marshalDescriptorBytes=f.GetMarshallingDescriptor().IsNil?null:Convert.ToHexString(md.GetBlobBytes(f.GetMarshallingDescriptor())).ToLowerInvariant()};}).ToArray();
                results.Add(new{artifact=artifact["key"]!.GetValue<string>(),type=typeName,typeToken=$"0x{MetadataTokens.GetToken(typeHandle):x8}",baseType=TypeName(type.BaseType),attributes=type.Attributes.ToString(),layout=new{layout.PackingSize,layout.Size},fields,methods});
            }
        }
        var result=new{schemaVersion=1,complete=false,authority="Focused System.Reflection.Metadata plus System.Reflection.Emit OpCodes from the host framework; no vendor assembly loading/execution",manifest=manifest.DeepClone(),targets=results,limitations=new[]{"Metadata tokens are bound to the recorded artifact SHA-256/MVID.","CIL decoding and direct method token references do not prove original BAML/resource identity, connectionId branch activation or runtime event execution.","MemberRef types/signatures and MethodSpec target plus raw instantiation signature are metadata, not semantic generic substitution or runtime binding."}};
        File.WriteAllText(Path.Combine(output,outputName),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true})+Environment.NewLine);Console.WriteLine(JsonSerializer.Serialize(new{targets=results.Count,complete=false,runtimeExecuted=false}));
    }
}
